def semver_sort(versions):
    def parse_version(version):
        # Split build metadata
        if '+' in version:
            version, build = version.split('+', 1)
        else:
            build = None

        # Split pre-release
        if '-' in version:
            base, prerelease = version.split('-', 1)
        else:
            base = version
            prerelease = None

        # Parse MAJOR.MINOR.PATCH
        parts = base.split('.')
        major = int(parts[0])
        minor = int(parts[1]) if len(parts) > 1 else 0
        patch = int(parts[2]) if len(parts) > 2 else 0

        # Parse pre-release identifiers
        if prerelease:
            identifiers = prerelease.split('.')
            prerelease_tuple = []
            for identifier in identifiers:
                if identifier.isdigit():
                    prerelease_tuple.append((0, int(identifier)))
                else:
                    prerelease_tuple.append((1, identifier))
            prerelease_tuple = tuple(prerelease_tuple)
        else:
            prerelease_tuple = None

        return (major, minor, patch, prerelease_tuple)

    def sort_key(item):
        version_str, index = item
        major, minor, patch, prerelease_tuple = parse_version(version_str)

        # Versions with pre-release sort before versions without
        if prerelease_tuple is None:
            prerelease_sort = (1,)  # No pre-release: sorts after
        else:
            prerelease_sort = (0, prerelease_tuple)  # With pre-release: sorts before

        return (major, minor, patch, prerelease_sort, index)

    # Add original index to maintain stable sort for equal versions
    indexed_versions = [(v, i) for i, v in enumerate(versions)]
    sorted_versions = sorted(indexed_versions, key=sort_key)

    return [v for v, _ in sorted_versions]

